targets.expr:
label_replace(
  sum(
    sum_over_time(
      aio_broker_connect_route_replication_correctness{cluster="$cluster"}[10m]
    )
  )
  /
  sum(
    count_over_time(
      aio_broker_connect_route_replication_correctness{cluster="$cluster"}[10m]
    )
  ),
  "_", "Connect", "__name__", ".*"
)
OR on() vector(404)

label_replace(
  sum(
    sum_over_time(
      aio_broker_publish_route_replication_correctness{cluster="$cluster"}[10m]
    )
  )
  /
  sum(
    count_over_time(
      aio_broker_publish_route_replication_correctness{cluster="$cluster"}[10m]
    )
  ),
  "_", "Publish", "__name__", ".*"
)
OR on() vector(404)

label_replace(
  sum(
    sum_over_time(
      aio_broker_subscribe_route_replication_correctness{cluster="$cluster"}[10m]
    )
  )
  /
  sum(
    count_over_time(
      aio_broker_subscribe_route_replication_correctness{cluster="$cluster"}[10m]
    )
  ),
  "_", "Subscribe", "__name__", ".*"
)
OR on() vector(404)

label_replace(
  (
    sum( # Total signals for 10m
      count_over_time(
        aio_broker_message_delivery_check_total_timeouts{cluster="$cluster"}[10m]
      )
    )
    -
    sum( # Total failures for 10m
      sum_over_time(
        aio_broker_message_delivery_check_total_timeouts{cluster="$cluster"}[10m]
      )
    )
  )
  / # Divide by total signals to get success rate
  sum( 
    count_over_time(
      aio_broker_message_delivery_check_total_timeouts{cluster="$cluster"}[10m]
    )
  ),
  "_", "Message Delivery", "__name__", ".*"
)
OR on() vector(404)

label_replace(
  sum(
    sum_over_time(
      aio_broker_ping_correctness{cluster="$cluster"}[10m]
    )
  )
  /
  sum(
    count_over_time(
      aio_broker_ping_correctness{cluster="$cluster"}[10m]
    )
  ),
  "_", "Ping", "__name__", ".*"
)
OR on() vector(404)

sum by(_)(label_replace(
        increase(aio_opc_mqtt_message_publishing_duration_count{
            cluster="$cluster",aio_opc_mqtt_publish_result!~"(success|nomatchingsubscribers)"
        }[5m:1m])
    ,'_','Connector:publishError:$1','aio_opc_mqtt_publish_result','(.*)')) or
sum by (_)(label_replace(
        increase(aio_opc_session_connect_duration_count{
            cluster="$cluster",aio_opc_module_type="opcua-connector",aio_opc_connect_result!="success"
        }[5m:1m])
    ,'_','Connector:connectError:$1','aio_opc_connect_result','(.*)')) or
vector(0)>0

sum by (_)(
    label_replace(increase(aio_dataflow_errors{cluster='$cluster'}[5m:1m]),'_','Dataflows:$1','errorcode','(.*)')
)

label_replace(
    sum(
        kube_daemonset_status_desired_number_scheduled{cluster="$cluster",namespace=~"$namespace",daemonset=~".*"} or
        kube_deployment_spec_replicas{cluster="$cluster",namespace=~"$namespace",deployment=~".*"} or
        kube_statefulset_status_replicas{cluster="$cluster",namespace=~"$namespace",statefulset=~".*"}
    ) - sum (
    label_replace(label_join(
        kube_daemonset_status_number_ready{cluster="$cluster",namespace=~"$namespace",daemonset=~".*"} or
        kube_deployment_status_replicas_ready{cluster="$cluster",namespace=~"$namespace",deployment=~".*"} or
        kube_statefulset_status_replicas_ready{cluster="$cluster",namespace=~"$namespace",statefulset=~".*"}
        ,"workloadName", "", "deployment", "daemonset", "replicaset", "statefulset")
        ,"workloadType", "$1", "__name__", "kube_(.*)_status_.*")
),"_","NOT-Ready","","")

#############################
# Node Memory Usage Pecent
  min by (node) (label_replace(
    (100 * sum by (instance)
      (node_memory_MemTotal_bytes{cluster="$cluster"} 
      - node_memory_MemFree_bytes{cluster="$cluster"} 
      - node_memory_Buffers_bytes{cluster="$cluster"} 
      - node_memory_Cached_bytes{cluster="$cluster"}) 
    / sum by(instance) (node_memory_MemTotal_bytes{cluster="$cluster"}))
    #* on (instance) group_left(node) label_replace(
    #  max by(internal_ip,node) (kube_node_info),"instance","$1:9100","internal_ip","(.*)") # Node Info
      ,"node","$1","instance","(.*)")
  )

sum by(_)(
    label_replace(
        aio_opc_asset_count{cluster='$cluster'}
    ,'_','assets','','')
)

sum by(_)(
    label_replace(
        aio_opc_asset_datapoint_count{cluster='$cluster'}
    ,'_','datapoints','','')
)

sum by(_)(
    label_replace(
        aio_broker_store_total_sessions{cluster='$cluster'}
    ,'_','sessions','','')
)

sum by(_)(
    label_replace(
        aio_broker_store_subscriptions{cluster='$cluster'}
    ,'_','subscriptions','','')
)

sum by(_)(
    label_replace(
        aio_broker_store_shared_subscriptions{cluster='$cluster'}
    ,'_','shared subscriptions','','')
)
